  /// Obtiene las localidades para un municipio dado de forma segura.
  /// Si no se encuentra coincidencia exacta, busca coincidencias parciales.
  static List<String> obtenerLocalidades(String? municipio) {
    if (municipio == null || municipio.trim().isEmpty) return const [];
    final m = municipio.trim();
    if (localidadesPorMunicipio.containsKey(m)) {
      return localidadesPorMunicipio[m]!;
    }
    // Intentar buscar sin el sufijo "zona (...)" o coincidencia insensible a mayúsculas
    final mLower = m.toLowerCase();
    for (final entry in localidadesPorMunicipio.entries) {
      if (entry.key.toLowerCase() == mLower ||
          entry.key.toLowerCase().startsWith(mLower) ||
          mLower.startsWith(entry.key.toLowerCase().split(" zona")[0])) {
        return entry.value;
      }
    }
    return const [];
  }
